{
    "name": "eric",
    "description": "Search eric.ed.gov",
    "parameters": {
      "type": "object",
      "properties": {
        "search": {
          "type": "string",
          "description": "Searching on core fields or on specific ERIC field names. ERIC will look for your search terms across a set of key ERIC fields: title, author, source, abstract and descriptor. You can also enter an ERIC accession number (ERIC ID) to search for the ERIC document itself, as well as documents that mention or cite the document by ID. An ISBN, ISSN, EISSN or IES Grant/Contract Number may also be entered directly into the search box."
        }
      },
      "required": [
        "search"
      ]
    }
  }
